import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <cstdint>
__device__ __forceinline__ float sigmoidf(float v) {
    return 1.0f / (1.0f + __expf(-v));
}
__device__ __forceinline__ float4 sigmoid4(float4 v) {
    v.x = sigmoidf(v.x);
    v.y = sigmoidf(v.y);
    v.z = sigmoidf(v.z);
    v.w = sigmoidf(v.w);
    return v;
}
// Memory-bound elementwise kernel. Each thread keeps several independent
// 16-byte (float4) transactions in flight (ILP) to raise DRAM utilization,
// while the grid is sized to fill the device (persistent-style) so the
// block-cyclic loop stays fully coalesced within each unrolled step.
constexpr int TPB = 128;
constexpr int ILP = 4;
__global__ void sigmoid_kernel(const float* __restrict__ x,
                               float* __restrict__ y,
                               long long n,
                               int aligned) {
    long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    if (aligned) {
        long long n4 = n >> 2;
        const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x);
        float4* __restrict__ y4 = reinterpret_cast<float4*>(y);
        const long long chunk = (long long)blockDim.x * ILP;   // float4 per block/iter
        const long long gstep = (long long)gridDim.x * chunk;  // global stride in float4
        for (long long base = (long long)blockIdx.x * chunk; base < n4; base += gstep) {
            float4 v[ILP];
#pragma unroll
            for (int k = 0; k < ILP; ++k) {
                const long long idx = base + (long long)k * blockDim.x + threadIdx.x;
                if (idx < n4) {
                    v[k] = x4[idx];   // independent, coalesced 16B loads
                }
            }
#pragma unroll
            for (int k = 0; k < ILP; ++k) {
                const long long idx = base + (long long)k * blockDim.x + threadIdx.x;
                if (idx < n4) {
                    y4[idx] = sigmoid4(v[k]);
                }
            }
        }
        long long baseS = n4 << 2;
        long long rem = n & 3;
        if (tid < rem) {
            y[baseS + tid] = sigmoidf(x[baseS + tid]);
        }
    } else {
        long long stride = (long long)gridDim.x * blockDim.x;
        for (long long i = tid; i < n; i += stride) {
            y[i] = sigmoidf(x[i]);
        }
    }
}
torch::Tensor sigmoid_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "Input must be float32");
    auto xc = x.contiguous();
    auto y = torch::empty_like(xc);
    long long n = xc.numel();
    if (n == 0) {
        return y;
    }
    const float* xp = xc.data_ptr<float>();
    float* yp = y.data_ptr<float>();
    bool aligned = ((reinterpret_cast<uintptr_t>(xp) & 15) == 0) &&
                   ((reinterpret_cast<uintptr_t>(yp) & 15) == 0);
    int aligned_i = aligned ? 1 : 0;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    if (aligned) {
        long long n4 = n >> 2;
        const long long per_block = (long long)TPB * ILP;
        long long want = (n4 + per_block - 1) / per_block;
        if (want < 1) want = 1;
        int sm = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
        int max_active_per_sm = 0;
        cudaOccupancyMaxActiveBlocksPerMultiprocessor(&max_active_per_sm, sigmoid_kernel, TPB, 0);
        if (max_active_per_sm < 1) max_active_per_sm = 8;
        long long cap = (long long)sm * max_active_per_sm;  // one full resident wave, no partial-wave tail
        long long blocks = want < cap ? want : cap;
        if (blocks > 2147483647LL) blocks = 2147483647LL;
        sigmoid_kernel<<<(unsigned int)blocks, TPB, 0, stream>>>(xp, yp, n, aligned_i);
    } else {
        long long blocks = (n + TPB - 1) / TPB;
        if (blocks > 2147483647LL) blocks = 2147483647LL;
        if (blocks < 1) blocks = 1;
        sigmoid_kernel<<<(unsigned int)blocks, TPB, 0, stream>>>(xp, yp, n, aligned_i);
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return y;
}
"""
_cpp_src = "torch::Tensor sigmoid_forward(torch::Tensor x);"
_mod = load_inline(
    name="sigmoid_cuda_ext",
    cpp_sources=[_cpp_src],
    cuda_sources=[_cuda_src],
    functions=["sigmoid_forward"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _mod.sigmoid_forward(x)

